        {text:"Accessibility Specialist Superbadge",url:"https://trailhead.salesforce.com/content/learn/superbadges/superbadge_accessibility"},
        {text:"UX Designer Module",url:"https://trailhead.salesforce.com/content/learn/modules/ux-designer"},
        {text:"Exam Registration",url:"https://trailheadacademy.salesforce.com/certificate/exam-ux-designer---Plat-Des-201"}
